                <label class="block font-semibold sm:col-span-2" for="cash-movement-concept">Concepto obligatorio<textarea id="cash-movement-concept" rows="3" maxlength="200" wire:model="concept" aria-invalid="{{ $errors->has('concept') ? 'true' : 'false' }}" class="mt-2 rounded border border-slate-400 p-3" @disabled($resolved)></textarea></label>
